package com.ailab.system.report.provider;
import com.ailab.system.domain.LabAsset; import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import com.ailab.system.service.LabAssetRiskPolicy; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class AssetSummaryProvider extends AbstractLabDataSourceProvider { private final LabAssetRiskPolicy riskPolicy=new LabAssetRiskPolicy(); public AssetSummaryProvider(){super(ReportConfigCatalog.ASSET_SUMMARY,new LinkedHashSet<String>(Arrays.asList("id","assetNo","assetName","assetType","assetStage","ownerId","backupOwnerId","criticalFlag","status","backupOwnerStatus","singlePointRisk")));} @Override protected boolean supports(ReportPeriod.Kind kind){return true;} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>>r=copyRows(mapper().selectAssets(c));for(Map<String,Object>x:r)applyRisk(x);Map<String,Object>z=summaryCount(r);recomputeFilteredSummary(r,z);return section(c,s,r,z);} @Override protected void recomputeFilteredSummary(List<Map<String,Object>> rows,Map<String,Object> summary){int risk=0;for(Map<String,Object>x:rows)if(Boolean.TRUE.equals(x.get("singlePointRisk")))risk++;summary.put("singlePointRiskCount",risk);} @Override protected Object normalizeValue(String field,Object value){if("singlePointRisk".equals(field)&&value!=null)return Boolean.valueOf(value instanceof Boolean?(Boolean)value:"1".equals(String.valueOf(value))||"true".equalsIgnoreCase(String.valueOf(value)));return value;} private void applyRisk(Map<String,Object>x){LabAsset asset=new LabAsset();asset.setStatus((String)x.get("status"));asset.setAssetStage((String)x.get("assetStage"));asset.setCriticalFlag((String)x.get("criticalFlag"));asset.setBackupOwnerId(longValue(x.get("backupOwnerId")));asset.setBackupOwnerStatus((String)x.get("backupOwnerStatus"));riskPolicy.apply(asset);x.put("singlePointRisk",Boolean.valueOf(asset.isSinglePointRisk()));} private Long longValue(Object v){return v==null?null:Long.valueOf(String.valueOf(v));}}
